/// Why an edit happened. Only Typing+Typing and Deletion+Deletion coalesce, and only when adjacent.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum EditKind { Typing, Deletion, Paste, Replace, Indent, Programmatic }

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct HistoryEntry {
    pub forward: Transaction,
    pub inverse: Transaction,
    pub kind: EditKind,
    pub revision_before: Revision,
    pub revision_after: Revision,
    pub ranges_before: Vec<CharRange>, // selections, primary first
    pub ranges_after: Vec<CharRange>,
}

pub struct History {
    undo: Vec<HistoryEntry>,
    redo: Vec<HistoryEntry>,
    group_open: bool,
    saved_depth: Option<usize>, // undo.len() at the last save; None if that state became unreachable
}
impl History {
    pub fn new() -> Self;
    /// Records an already-applied transaction. Coalesces into the last entry when group_open
    /// or when kind allows and the new edit starts where the last one ended. Clears redo.
    pub fn record(&mut self, entry: HistoryEntry);
    pub fn begin_group(&mut self); pub fn end_group(&mut self);
    /// Applies the inverse to `buf`, moves the entry to redo, returns ranges_before.
    pub fn undo(&mut self, buf: &mut TextBuffer) -> Option<Vec<CharRange>>;
    pub fn redo(&mut self, buf: &mut TextBuffer) -> Option<Vec<CharRange>>;
    pub fn can_undo(&self) -> bool; pub fn can_redo(&self) -> bool;
    pub fn mark_saved(&mut self);
    pub fn is_modified(&self) -> bool; // saved_depth != Some(undo.len())
    pub fn clear(&mut self);
}
